<?php $money=static fn($v)=>'£'.number_format(((int)$v)/100,2);$query='from='.urlencode($from).'&to='.urlencode($to);$max=max(array_map(static fn($r)=>(int)$r['total'],$monthly)?:[1]); ?>
<header class="page-header"><div><div class="eyebrow">Financial performance</div><h1>Revenue Reports</h1><p>Track payments, outstanding balances, renewals and service performance.</p></div><a class="primary-button" href="/reports/export?type=payments&<?= $query ?>">Export payments CSV</a></header>
<form class="report-filters" method="get" action="/reports"><label>From<input type="date" name="from" value="<?= htmlspecialchars($from) ?>"></label><label>To<input type="date" name="to" value="<?= htmlspecialchars($to) ?>"></label><button class="primary-button">Apply date range</button><a class="secondary-button" href="/reports">Reset</a></form>
<section class="metric-grid report-metrics"><article class="metric-card"><span class="metric-icon green">£</span><div><small>Revenue received</small><strong><?= $money($metrics['revenue']) ?></strong><em>Net successful payments</em></div></article><article class="metric-card"><span class="metric-icon blue">▤</span><div><small>Invoiced</small><strong><?= $money($metrics['invoiced']) ?></strong><em>Within selected dates</em></div></article><article class="metric-card"><span class="metric-icon amber">◇</span><div><small>Outstanding</small><strong><?= $money($metrics['outstanding']) ?></strong><em>All unpaid balances</em></div></article><article class="metric-card"><span class="metric-icon lilac">!</span><div><small>Overdue</small><strong><?= $money($metrics['overdue']) ?></strong><em>Past their due date</em></div></article></section>
<section class="report-grid"><article class="report-card wide"><div class="panel-heading"><div><span class="eyebrow">Revenue trend</span><h2>Payments by month</h2></div><span class="pill"><?= date('j M Y',strtotime($from)) ?> – <?= date('j M Y',strtotime($to)) ?></span></div><?php if(!$monthly): ?><div class="empty-state"><span>↗</span><h3>No payments in this period</h3><p>Successful payments will appear here.</p></div><?php else: ?><div class="revenue-chart"><?php foreach($monthly as $row): $height=max(4,round(((int)$row['total']/$max)*100)); ?><div class="chart-column"><div class="chart-value"><?= $money($row['total']) ?></div><div class="chart-track"><span style="height:<?= $height ?>%"></span></div><small><?= date('M y',strtotime($row['month'].'-01')) ?></small></div><?php endforeach; ?></div><?php endif; ?></article><article class="report-card"><div class="panel-heading"><div><span class="eyebrow">Business activity</span><h2>Selected period</h2></div></div><div class="activity-stats"><div><strong><?= number_format($activity['customers']) ?></strong><span>New customers</span></div><div><strong><?= number_format($activity['orders']) ?></strong><span>New orders</span></div><div><strong><?= number_format($activity['invoices']) ?></strong><span>Invoices raised</span></div></div></article></section>
<section class="report-grid halves"><article class="report-card"><div class="panel-heading"><div><span class="eyebrow">Payment split</span><h2>Payment methods</h2></div></div><div class="breakdown-list"><?php if(!$providers): ?><p class="muted">No payments recorded.</p><?php endif; ?><?php foreach($providers as $row): ?><div><span><strong><?= htmlspecialchars(ucwords(str_replace('_',' ',$row['provider']))) ?></strong><small><?= number_format($row['transactions']) ?> transactions</small></span><b><?= $money($row['total']) ?></b></div><?php endforeach; ?></div></article><article class="report-card"><div class="panel-heading"><div><span class="eyebrow">Revenue type</span><h2>One-off and recurring</h2></div></div><div class="breakdown-list"><?php if(!$billing): ?><p class="muted">No linked revenue recorded.</p><?php endif; ?><?php foreach($billing as $row): ?><div><span><strong><?= htmlspecialchars(ucwords(str_replace('_',' ',$row['billing_type']))) ?></strong><small>Net revenue received</small></span><b><?= $money($row['total']) ?></b></div><?php endforeach; ?></div></article></section>
<section class="report-grid halves"><article class="report-card table-card"><div class="panel-heading"><div><span class="eyebrow">Service performance</span><h2>Top packages</h2></div></div><div class="report-table"><div class="table-row table-head"><span>Package</span><span>Customers</span><span>Revenue</span></div><?php if(!$packages): ?><p class="muted padded">No package revenue recorded.</p><?php endif; ?><?php foreach($packages as $row): ?><div class="table-row"><span><strong><?= htmlspecialchars($row['package_name']) ?></strong><small><?= number_format($row['transactions']) ?> payments</small></span><span><?= number_format($row['customers']) ?></span><span><strong><?= $money($row['total']) ?></strong></span></div><?php endforeach; ?></div></article><article class="report-card table-card"><div class="panel-heading"><div><span class="eyebrow">Customer value</span><h2>Top customers</h2></div></div><div class="report-table"><div class="table-row table-head"><span>Customer</span><span>Payments</span><span>Revenue</span></div><?php if(!$customers): ?><p class="muted padded">No customer revenue recorded.</p><?php endif; ?><?php foreach($customers as $row): ?><div class="table-row"><span><a href="/customers/<?= (int)$row['id'] ?>"><strong><?= htmlspecialchars($row['customer_name']) ?></strong></a><small><?= htmlspecialchars($row['account_number']) ?></small></span><span><?= number_format($row['payments']) ?></span><span><strong><?= $money($row['total']) ?></strong></span></div><?php endforeach; ?></div></article></section>
<section class="report-grid halves"><article class="report-card table-card"><div class="panel-heading"><div><span class="eyebrow">Needs attention</span><h2>Overdue invoices</h2></div><a href="/reports/export?type=outstanding&<?= $query ?>">Export CSV</a></div><div class="report-table compact"><div class="table-row table-head"><span>Invoice</span><span>Due</span><span>Balance</span></div><?php if(!$overdue): ?><p class="muted padded">No overdue invoices. Lovely.</p><?php endif; ?><?php foreach(array_slice($overdue,0,8) as $row): ?><div class="table-row"><span><a href="/invoices/<?= (int)$row['id'] ?>"><strong><?= htmlspecialchars($row['invoice_number']) ?></strong></a><small><?= htmlspecialchars($row['customer_name']) ?></small></span><span><?= date('j M Y',strtotime($row['due_date'])) ?></span><span><strong><?= $money($row['balance_due']) ?></strong></span></div><?php endforeach; ?></div></article><article class="report-card table-card"><div class="panel-heading"><div><span class="eyebrow">Next 60 days</span><h2>Upcoming renewals</h2></div><a href="/reports/export?type=renewals&<?= $query ?>">Export CSV</a></div><div class="report-table compact"><div class="table-row table-head"><span>Service</span><span>Renews</span><span>Value</span></div><?php if(!$renewals): ?><p class="muted padded">No renewals in the next 60 days.</p><?php endif; ?><?php foreach(array_slice($renewals,0,8) as $row): ?><div class="table-row"><span><a href="/orders/<?= (int)$row['id'] ?>"><strong><?= htmlspecialchars($row['description']) ?></strong></a><small><?= htmlspecialchars($row['customer_name']) ?></small></span><span><?= date('j M Y',strtotime($row['renews_at'])) ?></span><span><strong><?= $money($row['total_amount']) ?></strong></span></div><?php endforeach; ?></div></article></section>
